class Animal:
def __init__(self, name):
self.name = name
def speak(self):
raise NotImplementedError("subclass must implement speak()")
class Dog(Animal):
def speak(self):
return f"{self.name}: woof!"
class Cat(Animal):
def speak(self):
return f"{self.name}: meow"
for a in [Dog("Rex"), Cat("Mochi")]:
print(a.speak())

class Puppy(Dog):
def __init__(self, name, owner):
super().__init__(name) # call Dog.__init__
self.owner = owner
def speak(self):
base = super().speak()
return f"{base} (and wags tail)"
Multiple inheritance exists (class C(A, B):) and uses the MRO (method resolution order). Keep it simple — use single inheritance unless you have a strong reason.

import math
class Vec2:
def __init__(self, x, y):
self.x = x
self.y = y
def __repr__(self):
return f"Vec2({self.x}, {self.y})"
def __add__(self, other):
return Vec2(self.x + other.x, self.y + other.y)
def __eq__(self, other):
return self.x == other.x and self.y == other.y
def __abs__(self):
return math.hypot(self.x, self.y)
a = Vec2(1, 2)
b = Vec2(3, 4)
print(a + b) # Vec2(4, 6)
print(abs(a)) # 2.236...
print(a == Vec2(1, 2)) # True

class Circle:
def __init__(self, radius):
self.radius = radius
@property
def area(self):
return math.pi * self.radius ** 2
@property
def diameter(self):
return self.radius * 2
@diameter.setter
def diameter(self, value):
self.radius = value / 2
c = Circle(5)
print(c.area) # accessed like an attribute, not a method!
c.diameter = 20 # setter called, radius becomes 10
print(c.radius) # 10
@property lets you expose calculated values as if they were attributes, and add validation/setters later without breaking callers.

class Date:
def __init__(self, y, m, d):
self.y, self.m, self.d = y, m, d
@classmethod
def from_string(cls, s): # alternative constructor
y, m, d = map(int, s.split("-"))
return cls(y, m, d)
@staticmethod
def is_leap(year): # no self, no cls
return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)
d = Date.from_string("2026-05-21")
Date.is_leap(2024) # True
@classmethod — gets the class as cls. Used for alternative constructors.
@staticmethod — gets nothing. Used for utility functions that belong with the class logically.

A common OOP design rule: when you can use containment instead of inheritance, do.
# Inheritance approach (often wrong)
class Engine:
def start(self): print("vroom")
class Car(Engine): # "Car is an Engine"? — no, a Car *has* an Engine
pass
# Composition (better)
class Car:
def __init__(self):
self.engine = Engine()
def start(self):
self.engine.start()
Inheritance creates a tight, often-unwanted coupling. Composition keeps pieces interchangeable.

Write a class BankAccount with deposit(amount), withdraw(amount), and balance (read-only). Reject withdrawals that would overdraw. Track all transactions in a list.
Solution
class BankAccount:
def __init__(self, owner, opening=0):
self.owner = owner
self._balance = opening
self.history = []
@property
def balance(self):
return self._balance
def deposit(self, amount):
if amount <= 0:
raise ValueError("amount must be positive")
self._balance += amount
self.history.append(("deposit", amount))
def withdraw(self, amount):
if amount > self._balance:
raise ValueError("insufficient funds")
self._balance -= amount
self.history.append(("withdraw", amount))

Implement a Stack class supporting:
push(x)
pop()
len(s)
bool(s) — False if empty
repr(s) — shows contents
Solution
class Stack:
def __init__(self):
self._items = []
def push(self, x):
self._items.append(x)
def pop(self):
return self._items.pop()
def __len__(self):
return len(self._items)
def __bool__(self):
return bool(self._items)
def __repr__(self):
return f"Stack({self._items!r})"
